import { useCallback, useState, useEffect } from 'react'
import { Container, CustomText, Button } from '../../../../../../components'
import { LANG_STRINGS, ERROR_LANG } from '../../../../../../lang/index'
import { UserDataStyle, ButtonWrapper } from './index.style'
import PolicyStepsHeader from '../../../../../../components/PolicyStepsHeader'
import { STEPS } from '../../../constant'
import { useHistory } from 'react-router-dom'
import { useParams } from 'react-router'
import { useGetRegionalCodes, useGetEwDetails, useUpdateExtendedWarrantyDraft, useUpdateCustomerExtendedWarrantyDraft, useGetCustomerEwDetails } from '../../../state/hooks/useExtendedWarrantyState'
import DynamicFormV3 from '../../../../../../components/DynamicFormV3/dynamicFormV3'
import { regex } from '../../../../../../constants/regex'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { useLoaderContextValue, useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import CircularLoader from '../../../../../../components/CircularLoader'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { useUpdateGlobal } from '../../../../../../state/globalState/hooks/useGlobalContext'
import { setToLocalStorage } from '../../../../../../helpers/localstorage'
import { CUSTOMER_FLOW } from '../../../../../../constants/cookies'

function UserDataContainer () {
  const history = useHistory()
  const { draftId } = useParams()
  const [{ globalState: { isLoggedIn } = { } }] = useUpdateGlobal()
  const [{ getRegionCodeData = [] }, getRegionCodesRequest] = useGetRegionalCodes()
  const [{ getEwDetailsData = {} }, getEwDetailsRequest] = useGetEwDetails()
  const [{ getCustomerEwDetailsData = {} }, getCustomerEwDetailsReq] = useGetCustomerEwDetails()
  const [, updateExtendedWarrantyDraftRequest] = useUpdateExtendedWarrantyDraft()
  const [, updateCustomerExtendedWarrantyDraftRequest] = useUpdateCustomerExtendedWarrantyDraft()
  const [{ updateExtendedWarrantyDraftStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [formValues, setFormValues] = useState({ personData: { name: '', address: '', mobile_no: '', email: '' }, vehicleData: { region_data: '', odometer_value: '', machine_number: '', chasis_number: '', plate_number: '', back_plate_number: '' }, docUpload: { ktp_url: '', stnk_url: '', odometer_url: '' } })
  // eslint-disable-next-line no-unused-vars
  const [isUserBlurred, setUserBlurred] = useState(false)
  const [{ GET_REGION_CODE_LOADER }] = useLoaderContextValue()
  const [formValid, setFormValid] = useState(false)

  useEffect(() => {
    if (isLoggedIn && draftId) {
      getEwDetailsRequest({ draftQuoteId: draftId })
    } else if (draftId) {
      setToLocalStorage(CUSTOMER_FLOW, 'true')
      getCustomerEwDetailsReq({ draftQuoteId: draftId })
    }
    getRegionCodesRequest()
  }, [getRegionCodesRequest, getEwDetailsRequest, draftId, getCustomerEwDetailsReq, isLoggedIn])

  useEffect(() => {
    if (updateExtendedWarrantyDraftStatus === 'success') {
      history.push({
        pathname: `/extended_warranty/confirmation/${draftId}`
      })
    } else if (updateExtendedWarrantyDraftStatus !== undefined) {
      ShowSnackbar.error({
        visible: true,
        text: `${ERROR_LANG.errorWhileUpdating}`
      })
    }
    resetError(['updateExtendedWarrantyDraftStatus'])
  }, [updateExtendedWarrantyDraftStatus, draftId, history, resetError])

  const handleBackButton = useCallback(() => {
    history.push({
      pathname: `/extended_warranty/package_detail/${draftId}`,
      state: {
        activeTab: 0
      }
    })
  }, [history, draftId])

  const handlePersonChange = (name, value) => {
    setFormValues((formValues) => {
      const newFormValues = { ...formValues }
      newFormValues.personData = {
        ...newFormValues.personData,
        [name]: value
      }
      return newFormValues
    })
  }

  const handleVehicleDataChange = (name, value) => {
    setFormValues((formValues) => {
      const newFormValues = { ...formValues }
      newFormValues.vehicleData = {
        ...newFormValues.vehicleData,
        [name]: value
      }
      return newFormValues
    })
  }

  const handleDocumentDataChange = (name, value) => {
    setFormValues((formValues) => {
      const newFormValues = { ...formValues }
      newFormValues.docUpload = {
        ...newFormValues.docUpload,
        [name]: value
      }
      return newFormValues
    })
  }

  const personDetailsformData = () => ({
    fieldData: [
      {
        label: 'Nama sesuai KTP',
        type: 'input',
        name: 'name',
        required: true,
        validator: (value = '') => {
          if (regex.nameRegexAlphanumericButContainAtleastTwoCharacters.test(value)) {
            return ''
          }
          return LANG_STRINGS.nameShouldContain2CharacterAtleast
        }
      },
      {
        label: 'Alamat Sesuai KTP',
        type: 'input',
        name: 'address',
        required: true
      },
      {
        label: 'Nomor Ponsel',
        type: 'input',
        name: 'mobile_no',
        required: true,
        validator: (value = '') => {
          if (!(['+62', '62', '08'].some((pre) => value.startsWith(pre)))) return ERROR_LANG.phoneNumberNotStartsWith62
          if (value.startsWith('+62') && value.length > 15) return ERROR_LANG.max15DigitAllowed
          if (value.length > 14) return ERROR_LANG.max14DigitAllowed
          if (!regex.phoneRegex.test(value)) return ERROR_LANG.phoneNumberError
          if (value.length < 9) return ERROR_LANG.minimum8digits
        }
      },
      {
        label: 'Email',
        type: 'input',
        name: 'email',
        message: LANG_STRINGS.emailAdditionalInfoEW,
        required: true,
        validator: (value = '') => {
          if (!regex.emailRegex.test(value)) {
            return ERROR_LANG.emailRequiredError
          }
          return ''
        }
      }
    ]
  })

  const vehicleDetailFormData = () => ({
    fieldData: [
      {
        label: 'Nomor Rangka',
        type: 'input',
        name: 'chasis_number',
        validator: (value = '') => {
          if (!regex.alphaNumeric.test(value) || value.length < 10) {
            return ERROR_LANG.incorrectFormat
          }
          return ''
        }
      },
      {
        label: 'Nomor Mesin',
        type: 'input',
        name: 'machine_number',
        validator: (value = '') => {
          if (!regex.alphaNumeric.test(value)) {
            return ERROR_LANG.incorrectFormat
          }
          if (value.length < 5) {
            return ERROR_LANG.minimum5digits
          }
          return ''
        }
      },
      {
        label: 'Odometer',
        type: 'input',
        name: 'odometer_value',
        validator: (value = '') => {
          if (!regex.numberDecimal.test(value)) {
            return ERROR_LANG.incorrectFormat
          }
          if (value.length > 8) {
            return ERROR_LANG.maximum8digits
          }
          return ''
        }
      },
      {
        label: 'Kode Daerah Plat',
        type: 'autoSearchSelect',
        name: 'region_data',
        options: getRegionCodeData,
        displayKey: 'region_code',
        dataKey: 'region_code'
      },
      {
        type: 'two-inputs',
        label1: 'Nomor Plat',
        name1: 'plate_number',
        label2: 'Kode Belakang Plat',
        name2: 'back_plate_number',
        validator1: (value = '') => {
          if (!regex.number.test(value)) {
            return ERROR_LANG.incorrectFormat
          }
          if (value.length > 4) {
            return ERROR_LANG.maximum4digits
          }
          return ''
        },
        validator2: (value = '') => {
          if (!regex.alphabets.test(value)) {
            return ERROR_LANG.incorrectFormat
          }
          return ''
        }
      }
    ]
  })

  const docUploadFormData = () => ({
    fieldData: [
      {
        label: 'Foto KTP',
        type: 'upload',
        name: 'ktp_url'
      },
      {
        label: 'Foto STNK',
        type: 'upload',
        name: 'stnk_url'
      },
      {
        label: 'Foto Odometer',
        type: 'upload',
        name: 'odometer_url'
      }
    ]
  })

  useEffect(() => {
    const validateForm = (formData, formValues) => {
      const { fieldData = [] } = formData()
      for (let i = 0; i < fieldData.length; i++) {
        const { name, name1, name2, validator, validator1, validator2 } = fieldData[i]
        if (!(formValues[name] || (formValues[name1] && formValues[name2]))) {
          return false
        }
        if (validator && validator(formValues[name])) {
          return false
        }
        if (validator1 && validator1(formValues[name1])) {
          return false
        }
        if (validator2 && validator2(formValues[name2])) {
          return false
        }
      }
      return true
    }

    const vehicleFormValid = validateForm(vehicleDetailFormData, formValues.vehicleData)
    const personFormValid = validateForm(personDetailsformData, formValues.personData)
    const docUploadFormValid = validateForm(docUploadFormData, formValues.docUpload)

    setFormValid(vehicleFormValid && personFormValid && docUploadFormValid)
  }, [formValues])

  const handleSubmit = () => {
    const payload = {
      stnk_url: formValues.docUpload.stnk_url,
      ktp_url: formValues.docUpload.ktp_url,
      odometer_url: formValues.docUpload.odometer_url,
      region_code: formValues.vehicleData.region_data?.region_code,
      region_data: formValues.vehicleData.region_data,
      machine_number: formValues.vehicleData.machine_number,
      vehicle_plate_no: formValues.vehicleData.plate_number + formValues.vehicleData.back_plate_number,
      chasis_number: formValues.vehicleData.chasis_number,
      odometer_value: formValues.vehicleData.odometer_value,
      customer_data: {
        name: formValues.personData.name,
        mobile_no: formValues.personData.mobile_no,
        email: formValues.personData.email,
        ktp_url: formValues.docUpload.ktp_url,
        customer_address: {
          address: formValues.personData.address
        }
      }
    }
    if (isLoggedIn) {
      updateExtendedWarrantyDraftRequest({
        body: {
          section: 'insured_object',
          sub_section: 'vehicle_photos',
          data: {
            ...getEwDetailsData.policy_details,
            ...payload
          }
        },
        draftQuoteId: draftId
      })
    } else {
      updateCustomerExtendedWarrantyDraftRequest({
        body: {
          section: 'insured_object',
          sub_section: 'vehicle_photos',
          data: {
            ...getEwDetailsData.policy_details,
            ...payload
          }
        },
        draftQuoteId: draftId
      })
    }
  }

  return (
    <Container
      title={LANG_STRINGS.extendedWarranty}
      showInnerHeader
      onClose={() => history.replace('/dashboard')}
      showCloseIcon
      displayBackButton
      hideBottomTabs
      onBackClick={handleBackButton}
    >
      <CircularLoader
        isLoading={GET_REGION_CODE_LOADER}
      >
        <PolicyStepsHeader
          stepsData={STEPS}
          activeCount={3}
          prevActive={{ 1: true, 2: true }}
        />
        <UserDataStyle>
          <CustomText
            size='15px'
            color={AgentColorPallette.regular}
            weight={700}
            bottom='20px'
          >
            Detail Personal
          </CustomText>
          <DynamicFormV3
            values={formValues.personData}
            onChange={handlePersonChange}
            formData={personDetailsformData()}
            setUserBlurred={setUserBlurred}
            formValues={formValues}
          />
          <CustomText
            size='15px'
            color={AgentColorPallette.regular}
            weight={700}
            top='20px'
            bottom='20px'
          >
            Detail Kendaraan
          </CustomText>
          <DynamicFormV3
            values={formValues.vehicleData}
            onChange={handleVehicleDataChange}
            formData={vehicleDetailFormData()}
            setUserBlurred={setUserBlurred}
            formValues={formValues}
          />
          <CustomText
            size='15px'
            color={AgentColorPallette.regular}
            weight={700}
            top='20px'
            bottom='20px'
          >
            Foto Dokumen
          </CustomText>
          <DynamicFormV3
            values={formValues.docUpload}
            onChange={handleDocumentDataChange}
            formData={docUploadFormData()}
            setUserBlurred={setUserBlurred}
            formValues={formValues}
          />
        </UserDataStyle>
      </CircularLoader>
      <ButtonWrapper>
        <Button className='submit-button' disabled={!formValid} onClick={handleSubmit}>
          {LANG_STRINGS.previousContinue}
        </Button>
      </ButtonWrapper>
    </Container>
  )
}

export default UserDataContainer
